    @classmethod
    def from_chain_file(cls, path: str, experiment_name: Optional[str] = None) -> "EvidenceStore":
        """Load from an existing chain JSON file."""
        chain = VerificationChain.load_json(path)
        if experiment_name is None:
            # Infer experiment name from directory or filename
            p = Path(path)
            experiment = p.parent.name if p.parent.name != "." else p.stem
            # If the filename is the default, try to get from metadata
            if experiment == "experiment_chain":
                # Check first record for experiment metadata
                records = chain.records
                if records:
                    first_body = records[0].get("sealed_body", {})
                    exp_from_meta = first_body.get("metadata", {}).get("experiment")
                    if exp_from_meta:
                        experiment = exp_from_meta
        else:
            experiment = experiment_name
        return cls(chain, experiment)
